import { TicketRow, MENU_PANEL } from "./04-sla-monitoring/row";
import records from "./04-sla-monitoring/data";
export default function DataTablesSlaMonitoring() {
const artemisInstanceId = useArtemisInstanceId();

    const reduce = useReducedMotion();
    const [query, setQuery] = useState("");
    const [focused, setFocused] = useState(false);
    const [status, setStatus] = useState("All statuses");
    const [sort, setSort] = useState<{
        key: number;
        direction: "asc" | "desc";
    } | null>(null);
    const [page, setPage] = useState(1);
    const [perPage, setPerPage] = useState(6);
    const [selected, setSelected] = useState<Set<string>>(new Set());
    const filtered = useMemo(() => {
        const q = query.trim().toLowerCase();
        const rows = records.filter(ticket => (status === "All statuses" || ticket.status === status) && (!q || [ticket.id, ticket.subject, ticket.account, ticket.owner].some(value => value.toLowerCase().includes(q))));
        if (sort) {
            const key = (["id", "subject", "account", "owner", "priority", "status"] as const)[sort.key];
            rows.sort((a, b) => (sort.direction === "asc" ? 1 : -1) * a[key].localeCompare(b[key]));
        }
        return rows;
    }, [query, status, sort]);
    const pages = Math.max(1, Math.ceil(filtered.length / perPage));
    const current = Math.min(page, pages);
    const visible = filtered.slice((current - 1) * perPage, current * perPage);
    const allSelected = visible.length > 0 && visible.every(ticket => selected.has(ticket.id));
    const someSelected = visible.some(ticket => selected.has(ticket.id));
    const toggle = (id: string, checked: boolean) => setSelected(old => { const next = new Set(old); if (checked)
        next.add(id);
    else
        next.delete(id); return next; });
    const toggleAll = (checked: boolean) => setSelected(old => { const next = new Set(old); for (const ticket of visible) {
        if (checked)
            next.add(ticket.id);
        else
            next.delete(ticket.id);
    } return next; });
