                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-funnel art:size-4" aria-hidden="true">
                  <path d="M10 20a1 1 0 0 0 .553.895l2 1A1 1 0 0 0 14 21v-7a2 2 0 0 1 .517-1.341L21.74 4.67A1 1 0 0 0 21 3H3a1 1 0 0 0-.742 1.67l7.225 7.989A2 2 0 0 1 10 14z"/>
                </svg>
               {status !== "All statuses" ? <span className="art:absolute art:top-2 art:right-2 art:size-1.5 art:rounded-full art:bg-primary"/> : null}</>} actions={["All statuses", "In review", "In progress", "Resolved", "Waiting"].map(label => ({ id: label, label, onSelect: () => setStatus(label), content: <>{label}{label === status ? <Check className="art:ml-auto art:size-3.5"/> : null}</> }))} panelClassName={MENU_PANEL + " art:w-44"}/>
              <AnimatedMenu label="Table options" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:focus-visible:outline-none art:hover:bg-muted art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring/40 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:size-9 art:shrink-0 art:h-9 art:rounded-full" icon={<>
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-sliders-horizontal art:size-4" aria-hidden="true">
                  <path d="M10 5H3"/>
